/**
 * Hochpräzise Such- und semantische Abfragemaschine
 */
Asynchrone Funktion „searchSentences“ exportieren(
  Abfrage:Zeichenfolge,
  Filter: SearchFilterOptions = {}
): Promise<{ results: SentenceItem[]; total:Anzahl; semanticMatches?: SemanticExplanationMatch[] }> {
  const all =waiteloadSentences();
  const normalizedQuery = normalizeText(query);
  const queryTokens = normalizedQuery ? normalizedQuery.split(' ').filter(Boolean) : [];

  const {
    cefr = 'alle',
    Abschnitt = 'alle',
    Kategorie = 'alle',
    Unterkategorie = 'alle',
    Grammatik = 'alle',
    Formalität = 'alle',
    Grenze = 50,
    Offset = 0,
  } = Filter;

  // Filterdurchlauf
  let filtered = all.filter(s => {
    if (cefr !== 'all' && s.cefr !== cefr) return false;
    if (section !== 'all' && s.section !==section) return false;
    if (category !== 'all' && s.category !== Category) return false;
    if (subcategory !== 'all' && s.subcategory !== subcategory) return false;
    if (grammar !== 'all' && !s.grammar.toLowerCase().includes(grammar.toLowerCase())) return false;
    if (formality !== 'all' && s.formality.toLowerCase() !== formality.toLowerCase()) return false;
    return true;
  });

  if (!normalizedQuery) {
    const total = filtered.length;
    const paginiert = gefiltert. Slice(Offset, Offset + Limit);
    return { Ergebnisse: paginiert, insgesamt };
  }

  // Bewertungsalgorithmus
  interfaceScoredItem {
    item:SentenceItem;
    punktzahl:zahl;
    Aspekt: SemanticExplanationMatch['matchedAspect'];
  }

  const bewertet: ScoredItem[] = [];

  for (const s of filtered) {
    lass Score = 0;
    let matchedAspect: SemanticExplanationMatch['matchedAspect'] = 'english';

    const normEn = normalizeText(s.english);
    const normEg = normalizeText(s.arabicEg);
    const normFusha = normalizeText(s.arabicFusha);
    const normGrammar = normalizeText(s.grammar);
    const normPurpose = normalizeText(s.zweck);

    // Exakte vollständige Satzübereinstimmung
    if (normEn === normalizedQuery) {
      Punktzahl += 100;
      matchedAspect = 'english';
    } else if (normEg === normalizedQuery) {
      Punktzahl += 95;
      matchedAspect = 'arabic-eg';
    } else if (normFusha === normalizedQuery) {
      Punktzahl += 90;
      matchedAspect = 'arabic-fusha';
    }

    //Teilstring enthält
    if (normEn.includes(normalizedQuery)) {
      Punktzahl += 50;
      matchedAspect = 'english';
    } else if (normEg.includes(normalizedQuery)) {
      Punktzahl += 45;
      matchedAspect = 'arabic-eg';
    } else if (normFusha.includes(normalizedQuery)) {
      Punktzahl += 40;
      matchedAspect = 'arabic-fusha';
    } else if (normGrammar.includes(normalizedQuery)) {
      Punktzahl += 35;
      matchedAspect = 'Grammatik';
    } else if (normPurpose.includes(normalizedQuery)) {
      Punktzahl += 30;
      matchedAspect = 'Konzept';
    }

    // Token-Übereinstimmung
    let tokenMatches = 0;
    for (const token of queryTokens) {
      if (normEn.includes(token)) tokenMatches += 5;
      if (normEg.includes(token)) tokenMatches += 4;
      if (normFusha.includes(token)) tokenMatches += 3;
      if (s.vocabulary.some(v => normalizeText(v).includes(token))) tokenMatches += 4;
      if (s.tags.some(t => normalizeText(t).includes(token))) tokenMatches += 3;
    }
    Punktzahl += tokenMatches;

    if (Score > 0) {
      Scored.push({ item: s, Score, Aspect: matchedAspect });
    }
  }

  Scored.sort((a, b) => b.score - a.score);

  // Semantische Erklärungsübereinstimmungen für Top-Elemente
  const semanticMatches: SemanticExplanationMatch[] =Scored.slice(0, 5).map(s => {
    let nuance = '';
    if (s.item.grammar.toLowerCase().includes('past continuierlich')) {
      nuance = 'Die Vergangenheitsform zeigt, dass ein Ereignis zu einem bestimmten Zeitpunkt in der Vergangenheit stattfand.';
    } else if (s.item.grammar.toLowerCase().includes('present perfect continuierlich')) {
      nuance = 'Das Present Perfect Continuous Tense betont die Zeit aus der Vergangenheit und dauert bis zum Moment des Sprechens.';
    } else if (s.item.grammar.toLowerCase().includes('future perfect')) {
      nuance = 'Das Futur Perfekt drückt aus, dass ein Ereignis vor einem bestimmten Zeitpunkt in der Zukunft abgeschlossen sein wird.';
    } else if (s.item.grammar.toLowerCase().includes('indirect')) {
      nuance = 'Die Form der indirekten Bitte ist der Höhepunkt der diplomatischen Etikette in der englischen Kommunikation.';
    }
    zurück {
      Satz: s.item,
      SimilarityScore: Math.min(100, s.score),
      nuanceExplanationAr: Nuance,
      matchedAspect: s.aspect,
    };
  });

  const total = erzielt. Länge;
  const paginated =Scored.slice(Offset, Offset + Limit).map(s => s.item);

  zurück {
    Ergebnisse: paginiert,
    insgesamt,
    semanticMatches,
  };
}

/**
 * Deterministischer Tagessatz (identisch für alle Benutzer an einem bestimmten Tag)
 */
Asynchrone Funktion getDailySentence() exportieren: Promise<SentenceItem | null> {
  const all =waiteloadSentences();
  if (all. length === 0) return null;

  const today = new Date();
  const dayOfYear = Math.floor(
    (today.getTime() - neues Datum(today.getFullYear(), 0, 0).getTime()) / 1000 / 60 / 60 / 24
  );
  const index = Math.abs((dayOfYear * 97 + today.getFullYear()) % all.length);
  alle[Index] || zurückgeben alle[0];
}

/**
 * Deterministischer Satz der Woche
 */
Asynchrone Funktion getSentenceOfTheWeek() exportieren: Promise<SentenceItem | null> {
  const all =waiteloadSentences();
  if (all. length === 0) return null;

  const today = new Date();
  const WeekNumber = Math.ceil(
    ((today.getTime() - neues Datum(today.getFullYear(), 0, 1). getTime()) / 86400000 + 1) / 7
  );
  // Bevorzugen Sie B2 oder C1 für den Satz der Woche
  const b2c1 = all.filter(s => s.cefr === 'B2' || s.cefr === 'C1');
  const pool = b2c1.length > 0 ? b2c1:alle;
  const index = Math.abs((weekNumber * 31) % pool.length);
  Rückgabepool[Index] || pool[0];
}

